package com.app.controller; import com.app.dto.SocietyAttendanceWorkflowDtos.*; import com.app.security.UserPrincipal; import com.app.service.SocietyAttendanceWorkflowService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import java.time.LocalDate; import java.util.List;
@RestController @RequestMapping("/society/attendance-workflow") @RequiredArgsConstructor public class SocietyAttendanceWorkflowController {private final SocietyAttendanceWorkflowService service;@GetMapping("/status") public SheetDto status(@AuthenticationPrincipal UserPrincipal p,@RequestParam LocalDate date){return service.status(p.getAccountId(),date);}@PostMapping("/submit") public SheetDto submit(@AuthenticationPrincipal UserPrincipal p,@Valid @RequestBody SheetRequest r){return service.submit(p.getAccountId(),p.getUserId(),r.getAttendanceDate());}@PostMapping("/lock") public SheetDto lock(@AuthenticationPrincipal UserPrincipal p,@Valid @RequestBody SheetRequest r){return service.lock(p.getAccountId(),p.getUserId(),r.getAttendanceDate());}@PostMapping("/{attendanceId}/corrections") public CorrectionDto request(@AuthenticationPrincipal UserPrincipal p,@PathVariable Long attendanceId,@Valid @RequestBody CorrectionRequest r){return service.request(p.getAccountId(),p.getUserId(),attendanceId,r);}@GetMapping("/corrections") public List<CorrectionDto> pending(@AuthenticationPrincipal UserPrincipal p){return service.pending(p.getAccountId(),p.getUserId());}@PostMapping("/corrections/{id}/approve") public CorrectionDto approve(@AuthenticationPrincipal UserPrincipal p,@PathVariable Long id){return service.approve(p.getAccountId(),p.getUserId(),id);}}
